window.__meadowSearchReceiveShard([{"t":"t024 - markdown links","p":"t024%20-%20markdown%20links.html","b":"This test covers standard markdown link syntax. Link to a page in subdirectory: Linked Page Link to a deeper page: Deep Page Link to inlink-only page: Inlink Only Link to an image: Test Image Link outside the source graph: link not tracked External link whose text is bold and italic: bold and italic text External link wrapped around an image, like a README badge: External link with a title containing quotes: titled The next three links are other standard ways of writing the first link on this page. Each should lead to the same linked page. A reference-style link, with its destination defined at the bottom of the page: Linked Page A link with a title: Linked Page A link whose destination is in angle brackets, which allows spaces: Linked Page"}]);
